var time3 = Cesium.JulianDate.fromIso8601('2010-05-07T00:02:00');

var property = new Cesium.SampledProperty(Cesium.Rotation);
property.addSample(time1, 0);
property.addSample(time3, Cesium.Math.toRadians(350));

