export namespace BaiduImageryProvider {
    /**
     * 百度地图-无偏显示
     * @property url - 百度地图url
     * @property [maximumLevel] - 最大显示级别
     * @property [tileDiscardPolicy] - 卡片策略，该策略决定如果是一张无效瓦片就会删除. 如果要确保没有瓦片被删除,传递{@link NeverTileDiscardPolicy}参数.
     * @property [ellipsoid] - 椭球体. 不指定则使用WGS84椭球
     */
    type ConstructorOptions = {
        url: Resource | string;
        maximumLevel?: number;
        tileDiscardPolicy?: TileDiscardPolicy;
        ellipsoid?: Ellipsoid;
    };
}

/**
 * 提供百度无偏地图瓦片的API服务.
 * @example
 * var baidu = new Cesium.BaiduImageryProvider({
    url : 'https://earth.localdomain',
});
 * @param options - 初始化构造参数
 */
export class BaiduImageryProvider {
    constructor(options: BaiduImageryProvider.ConstructorOptions);
    /**
     * 瓦片数据源默认透明度, 0.0表示透明，1.0表示不透明.
     */
    defaultAlpha: number | undefined;
    /**
     * 瓦片数据源地球夜晚半球的混合透明度, 0.0表示透明，1.0表示不透明.
     */
    defaultNightAlpha: number | undefined;
    /**
     * 瓦片数据源地球白天半球的混合透明度, 0.0表示透明，1.0表示不透明.
     */
    defaultDayAlpha: number | undefined;
    /**
     * 瓦片数据源的明亮度.  1.0使用标准颜色.小于1.0变暗，大于1.0变明亮.
     */
    defaultBrightness: number | undefined;
    /**
     * 瓦片数据源的颜色反差.  1.0使用标准颜色.小于1.0减少反差值，大于1.0增加反差值.
     */
    defaultContrast: number | undefined;
    /**
     * 瓦片数据源的颜色色调. 0.0使用标准颜色.
     */
    defaultHue: number | undefined;
    /**
     * 瓦片数据源的颜色饱和度. 1.0使用标准饱和度.小于1.0减少饱和度，大于1.0增加饱和度.
     */
    defaultSaturation: number | undefined;
    /**
     * 瓦片数据源的灰度系数. 1.0使用标准灰度系数. 默认1.9
     */
    defaultGamma: number | undefined;
    /**
     * 瓦片数据源的纹理缩小值.
     */
    defaultMinificationFilter: TextureMinificationFilter;
    /**
     * 瓦片数据源的纹理放大值.
     */
    defaultMagnificationFilter: TextureMagnificationFilter;
    /**
     * 百度地图的Url.
     */
    readonly url: string;
    /**
     * 数据源代理.
     */
    readonly proxy: Proxy;
    /**
     * 瓦片宽度，单位像素. 在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly tileWidth: number;
    /**
     * 瓦片高度，单位像素. 在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly tileHeight: number;
    /**
     * 瓦片的最大级别. 在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly maximumLevel: number | undefined;
    /**
     * 瓦片的最小级别. 在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly minimumLevel: number;
    /**
     * 瓦片数据源的切片规则. 在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly tilingScheme: TilingScheme;
    /**
     * 瓦片数据源的空间范围.在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly rectangle: Rectangle;
    /**
     * 瓦片数据源的无效瓦片删除策略.在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly tileDiscardPolicy: TileDiscardPolicy;
    /**
     * 瓦片数据源的错误事件，当异步瓦片请求错误的时候发送事件.  通过订阅事件,提前发现潜在的瓦片问题并解决.  事件监听类型为{@link TileProviderError}.
     */
    readonly errorEvent: Event;
    /**
     * 瓦片数据源是否准备好开始正式使用.
     */
    readonly ready: boolean;
    /**
     * 当瓦片数据源准备好后返回一个promise外部使用.
     */
    readonly readyPromise: Promise<boolean>;
    /**
     * 瓦片数据源的证书.  在{@link BaiduImageryProvider#ready} 返回true前无法获取.
     */
    readonly credit: Credit;
    /**
     * Gets the credits to be displayed when a given tile is displayed.
     * @param x - The tile X coordinate.
     * @param y - The tile Y coordinate.
     * @param level - The tile level;
     * @returns The credits to be displayed when the tile is displayed.
     */
    getTileCredits(x: number, y: number, level: number): Credit[];
    /**
     * Requests the image for a given tile.  This function should
    not be called before {@link BaiduImageryProvider#ready} returns true.
     * @param x - The tile X coordinate.
     * @param y - The tile Y coordinate.
     * @param level - The tile level.
     * @param [request] - The request object. Intended for internal use only.
     * @returns A promise for the image that will resolve when the image is available, or
             undefined if there are too many active requests to the server, and the request
             should be retried later.  The resolved image may be either an
             Image or a Canvas DOM object.
     */
    requestImage(x: number, y: number, level: number, request?: Request): Promise<HTMLImageElement | HTMLCanvasElement> | undefined;
    /**
     * Picking features is not currently supported by this imagery provider, so this function simply returns
    undefined.
     * @param x - The tile X coordinate.
     * @param y - The tile Y coordinate.
     * @param level - The tile level.
     * @param longitude - The longitude at which to pick features.
     * @param latitude - The latitude at which to pick features.
     * @returns A promise for the picked features that will resolve when the asynchronous
                      picking completes.  The resolved value is an array of {@link ImageryLayerFeatureInfo}
                      instances.  The array may be empty if no features are found at the given location.
                      It may also be undefined if picking is not supported.
     */
    pickFeatures(x: number, y: number, level: number, longitude: number, latitude: number): Promise<ImageryLayerFeatureInfo[]> | undefined;
    /**
     * Gets or sets the URL to the Google Earth logo for display in the credit.
     */
    static logoUrl: string;
}

