/**
 * 采样高程工具，从地形或模型上采样真实高程，返回结果为角度制的经纬度坐标
 * @example
 * function callBackFuntion(result){
    var elevationPosition = result;
}
var tool = new Cesium.SampleElevationTool(viewer,positions,'model',callBackFuntion);
tool.start();
 * @param viewer - 场景视图对象
 * @param positions - 坐标数组,世界坐标Cartesian3
 * @param type - 数据类型，m3d模型缓存：'model'，地形：'terrain',通用：'general'
 * @param callBackFuntion - 用于返回结果的回调函数，参数result为结果，使用经纬度坐标Cartographic的数组进行存储
 */
export class SampleElevationTool {
    constructor(viewer: any, positions: any[], type: string, callBackFuntion: (...params: any[]) => any);
    /**
     * 采样高程
     * @param [options.level] - 采样精度，暂时仅支持地形采样精度设置
     */
    start(options: {
        level?: number;
    }): void;
}

