/**
 * 三角测量
 * @example
 * function callBack(arg){
   }
  var triangulationTool = new Cesium.TriangulationTool(viewer,{
  callBack:callBack,
           scaleByDistance: function(height) {
                 if (height < 30) {
                     return new NearFarScalar(30, 3, 180, 0);
                 } else if (height < 60) {
                     return new NearFarScalar(60, 3, 360, 0);
                 } else if (height < 120) {
                     return new NearFarScalar(120, 3, 720, 0);
                 } else if (height < 240) {
                     return new NearFarScalar(240, 2, 1200, 0);
                 } else if (height < 480) {
                     return new NearFarScalar(480, 2, 2400, 0);
                 } else if (height < 960) {
                     return new NearFarScalar(960, 2, 4800, 0);
                 } else if (height < 1920) {
                     return new NearFarScalar(1920, 2, 9600, 0);
                 } else if (height < 3840) {
                     return new NearFarScalar(3840, 2, 19200, 0);
                 } else if (height < 7680) {
                     return new NearFarScalar(7680, 2, 38400, 0);
                 } else if (height < 15360) {
                     return new NearFarScalar(15360, 2, 76800, 0);
                 } else if (height < 30720) {
                     return new NearFarScalar(30720, 2, 153600, 0);
                 } else if (height < 61440) {
                     return new NearFarScalar(61440, 2, 307200, 0);
                 } else if (height < 122880) {
                     return new NearFarScalar(122880, 2, 614400, 0);
                 } else if (height < 245760) {
                     return new NearFarScalar(245760, 2, 1228800, 0);
                 } else if (height < 491520) {
                     return new NearFarScalar(491520, 2, 2457600, 0);
                 } else if (height < 983040) {
                     return new NearFarScalar(983040, 2, 4915200, 0);
                 } else if (height < 1966080) {
                     return new NearFarScalar(1966080, 2, 9830400, 0);
                 } else if (height < 3932160) {
                     return new NearFarScalar(3932160, 1, 19660800, 0);
                 } else if (height < 7864320) {
                     return new NearFarScalar(7864320, 1, 39321600, 0);
                 } else if (height < 15728640) {
                     return new NearFarScalar(15728640, 1, 78643200, 0);
                 }
                 return new NearFarScalar(15728640, 1, 78643200, 0);
          }
  });
  triangulationTool.startTool();  //开始测量
  //triangulationTool.stopTool(); //结束测量
scene.camera.enableTerrainAdjustmentWhenLoading = false;
 * @param viewer - 视图
 * @param options - 包含以下属性的对象
 * @param [options.callBack = function(result, positions){}] - 回调函数
 * @param [options.labelCallBack = function(result, label){}] - 测量完毕后提示框的回调函数，可以覆盖提示内容
 * @param [options.disableDepthTestDistance = Number.POSITIVE_INFINITY] - 只要小于这个距离深度检测就会失效，就会一直显示在最前面 不会被遮挡
 * @param [options.lineColor] - 线颜色
 * @param [options.pointColor] - 点颜色
 * @param [options.lineMaterial] - 线材质
 * @param [options.style = LabelStyle.FILL] - label 文字的样式，支持填充、线框。填充和线框， FILL, OUTLINE, FILL_AND_OUTLINE
 * @param [options.font = '12pt 楷体'] - label 的字体以及大小 @see {@link https://html.spec.whatwg.org/multipage/canvas.html#text-styles}
 * @param [options.fillColor = Color.WHITE] - label 的字体颜色
 * @param [options.outlineColor = Color.WHITE] - label 文字线框的颜色
 * @param [options.outlineWidth = 4.0] - label 的外轮廓边线
 * @param [options.verticalOrigin = VerticalOrigin.BOTTOM] - label 的摆放位置
 * @param [options.showBackground = true] - 是否显示 label 的背景
 * @param [options.backgroundColor = new Color(0, 0, 0, 0.4)] - lable 背景的颜色
 * @param [options.pixelOffset = new Cartesian2(0, -4)] - label 相对于设定点的偏移位置
 * @param [options.showMoreInfo = true] - 是否显示详细信息。默认显示。
 * @param [options.enableABS = false] - 展示信息时是否使用绝对值。默认不使用。
 * @param [options.enableScaleByDistance = true] - 是否启用标签随视角高度缩放功能
 * @param [options.scaleByDistance = null] - 标签大小随视角高度缩放函数，用户可自定义，不传则使用默认函数,会传入一个当前的相机视角高度,返回一个NearFarScale函数对象，详见下方示例
 */
export class TriangulationTool {
    constructor(viewer: any, options: {
        callBack?: boolean;
        labelCallBack?: boolean;
        disableDepthTestDistance?: number;
        lineColor?: Color;
        pointColor?: Color;
        lineMaterial?: Material;
        style?: LabelStyle;
        font?: string;
        fillColor?: Color;
        outlineColor?: Color;
        outlineWidth?: number;
        verticalOrigin?: VerticalOrigin;
        showBackground?: boolean;
        backgroundColor?: Color;
        pixelOffset?: Cartesian2;
        showMoreInfo?: boolean;
        enableABS?: boolean;
        enableScaleByDistance?: number;
        scaleByDistance?: NearFarScalar;
    });
    /**
     * 开始测量
     */
    startTool(): void;
    /**
     * 结束测量
     */
    stopTool(): void;
    /**
     * 右键是否继续重新
     */
    rightClickReBegin: boolean;
    /**
     * 高差
     */
    verticalDiatance: number;
    /**
     * 直线距离
     */
    slantDiatance: number;
    /**
     * 水平距离
     */
    horizontalDiatance: number;
    /**
     * 计算两点之间的高程差
     * @param startPoint - 起始点
     * @param endPoint - 终止点
     */
    calculateByTwoPoints(startPoint: any, endPoint: any): void;
}

